import { Game } from '../src/engine.js';
import { actionCandidates, decisionCandidates } from './candidates.mjs';
import { encodeDecision } from './observation.mjs';
import { enrichPreview } from './preview.mjs';
import { teacherIndex } from './teacher.mjs';

// Known diagnostics, not holdout data. Every alternative is generated by rules.
export function preservationCases() {
 const specs = [
  {hero:'berserker',skill:'bloodyRoar',element:'fire',healing:0,expected:true},
  {hero:'berserker',skill:'bloodyRoar',element:'fire',healing:2,expected:false},
  {hero:'sealer',skill:'fireSeal',element:'fire',other:'earth',expected:true},
  {hero:'sealer',skill:'fireSeal',element:'fire',other:'earth',targetHand:1,expected:false},
  {hero:'sealer',skill:'fireSeal',element:'fire',response:true,expected:true},
  {hero:'guardianAngel',skill:'angelWall',element:'fire',expected:true},
  {hero:'priest',element:'water',other:'fire',expected:false},
  {hero:'windSwordmaster',skill:'galeArt',element:'fire',expected:false},
  {hero:'windSwordmaster',skill:'galeArt',element:'fire',response:true,expected:true},
  {hero:'marksman',skill:'flashTrap',element:'fire',expected:true},
  {hero:'marksman',skill:'precisionShot',element:'thunder',expected:false},
 ];
 return specs.flatMap((spec,caseIndex)=>[false,true].map(reverse=>{
  const game=new Game({seed:252690100+caseIndex,heroIds:[spec.hero,'none','none','none','none','none']});
  const ownSkills=new Set(game.player(0).getSkills().map(({skill})=>skill.id));
  const unique=game.deck.find(c=>c.type==='attack'&&c.element===spec.element&&(!spec.skill||c.hasUniqueSkill(spec.skill)));
  const ordinary=game.deck.find(c=>c!==unique&&c.type==='attack'&&c.element===(spec.other??spec.element)&&!c.uniqueSkills.some(s=>ownSkills.has(s)));
  if(!unique||!ordinary)throw Error('Missing same-role fixture '+JSON.stringify(spec));
  for(const card of reverse?[ordinary,unique]:[unique,ordinary])game.moveCard(card.id,{zone:'hand',playerId:0});
  while(game.player(0).hand.length<4)game.moveCard(game.deck.find(c=>c.name==='holyLight').id,{zone:'hand',playerId:0});
  for(const player of game.players.filter(p=>p.team!==game.player(0).team)){
   player.healing=spec.healing??0;
   if(spec.targetHand)game.moveCard(game.deck.find(c=>c.type==='attack').id,{zone:'hand',playerId:player.id});
  }
  game.startTurn(0);
  let request={type:'action'};
  if(spec.response){
   const attack=game.deck.find(c=>c.type==='attack'&&c.element===spec.element);
   game.moveCard(attack.id,{zone:'field'});
   const actor=game.player(1),target=game.player(0),attackTraits=attack.getTraits({game,playerId:1});
   request={type:'response',actor,target,attack,attackTraits,valid:target.hand.map((card,index)=>({card,index})).filter(({card})=>game.canRespond(attack,card,{actorId:1,targetId:0,attackTraits})),counterTargets:game.players.filter(p=>p.team!==target.team&&p.id!==actor.id),isCounter:false,shieldable:true};
  }
  const candidates=spec.response?decisionCandidates(game,request):actionCandidates(game,0);
  const input={game,playerId:0,request,candidates};const observation=encodeDecision(input);enrichPreview(observation);
  const uniqueIndices=candidates.flatMap((c,i)=>c?.index!=null&&game.player(0).hand[c.index]===unique?[i]:[]);
  if(!uniqueIndices.length)throw Error('Fixture unique attack not legal');
  return {name:`${spec.hero}-${spec.skill??'water'}-${caseIndex}`,spec,reverse,observation,baselineChoice:teacherIndex(input,process.argv.find(v=>v.startsWith('--policy='))?.slice(9) ?? 'v1.5'),uniqueIndices};
 }));
}
if(process.argv[1]===new URL(import.meta.url).pathname)console.log(JSON.stringify(preservationCases()));
